/**
 * Company branding constants — single source of truth so the logo and
 * credit line never drift out of sync between the app UI, PDF exports,
 * Excel exports, and the user manual.
 *
 * The logo is embedded as base64 (rather than read from /public at
 * runtime) so it works identically in local dev and in Vercel's
 * serverless functions without any filesystem-path assumptions.
 */

export const COMPANY_NAME = "Smile Food Products Limited";

/** Raw base64 PNG data (transparent background), no "data:" prefix — use this for server-side image embedding (PDFKit, ExcelJS). */
export const LOGO_BASE64 = "";

/** Ready-to-use <img src="..."> value for browser contexts. */
export const LOGO_DATA_URI = `data:image/png;base64,${LOGO_BASE64}`;

/** Decoded PNG buffer for server-side embedding (PDFKit `doc.image()`, ExcelJS `workbook.addImage()`). */
export function getLogoBuffer(): Buffer {
  return Buffer.from(LOGO_BASE64, "base64");
}

export const FOOTER_CREDIT_LINES = [
  // `Developed by the IT Department, ${COMPANY_NAME}`,
  "Designed & Developed by Md. Shanjeed Saif, Officer \u2013 IT"
];
